package com.footballacademy.services.scouting;
import com.footballacademy.model.*; import com.footballacademy.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class ScouterAssignmentService { private final ScoutingAssignmentRepository assignments; private final AcademyRepository academies; private final DivisionRepository divisions; private final ScouterRepository scouters; public ScouterAssignmentService(ScoutingAssignmentRepository assignments, AcademyRepository academies, DivisionRepository divisions, ScouterRepository scouters){this.assignments=assignments;this.academies=academies;this.divisions=divisions;this.scouters=scouters;} @Transactional public ScoutingAssignment assignScouter(Long academyId, Long divisionId, Long scouterId){ScoutingAssignment a=new ScoutingAssignment(); a.setAcademy(academies.findById(academyId).orElseThrow()); a.setDivision(divisions.findById(divisionId).orElseThrow()); a.setScouter(scouters.findById(scouterId).orElseThrow()); return assignments.save(a);} @Transactional public void revokeAssignment(Long assignmentId){ScoutingAssignment a=assignments.findById(assignmentId).orElseThrow(); a.setStatus(ScoutingStatus.REJECTED); assignments.save(a);} public List<ScoutingAssignment> getAssignments(Long scouterId){return assignments.findByScouter_Id(scouterId);} }
